// ── Encode current canvas state for server ──
// PROTOTYPE (option A, Brett-approved 2026-10-19): the ONLY change to main's
// save format code. Main floored each channel to 5 bits (v>>3) on save and
// decoded q<<3, so a colour could only ever get darker (≈ −3.5/channel per
// share once the engine had moved it off the grid; white came back as 248).
// Now: encode rounds to the NEAREST 5-bit level, decode expands by bit
// replication ((q<<3)|(q>>2): 0→0, 31→255). Same RGB555 + held-bit layout
// and size, so old rows load unchanged (decoded to the middle of their
// level instead of its floor) and main can still read new rows.
function q5(v){return Math.min(31,Math.round(v*31/255));}
function x5(q){return (q<<3)|(q>>2);}
function encodeForServer(){
  // Pack: high bit = stabilised, low 15 bits = quantised colour
  const arr = new Uint16Array(WT);
  for(let i=0;i<WT;i++){
    const c = cells[i].c||'#000000';
    const r=q5(parseInt(c.slice(1,3),16));
    const g=q5(parseInt(c.slice(3,5),16));
    const b=q5(parseInt(c.slice(5,7),16));
    const q = ((r&31)<<10)|((g&31)<<5)|(b&31);
    arr[i] = (cells[i].s>0 ? 0x8000 : 0) | q;
  }
  const bytes = new Uint8Array(arr.buffer);
  let bin='';
  for(let i=0;i<bytes.length;i++) bin+=String.fromCharCode(bytes[i]);
  return btoa(bin);
}

// ── Decode canvas state from server ──
function decodeFromServer(b64){
  try{
    const bin=atob(b64);
    const bytes=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
    const arr=new Uint16Array(bytes.buffer);
    for(let i=0;i<Math.min(WT,arr.length);i++){
      const q=arr[i]&0x7FFF;
      const r=x5((q>>10)&31);
      const g=x5((q>>5)&31);
      const b=x5(q&31);
      cells[i]={
        c:'#'+[r,g,b].map(v=>v.toString(16).padStart(2,'0')).join(''),
        s:(arr[i]&0x8000)?1:0
      };
    }
    return true;
  }catch(e){ console.error('Decode failed:',e); return false; }
}

